#!/usr/bin/env node
/**
 * fix-circular-generated-models.js
 *
 * The `gen-api-models` tool (io-utils) generates one io-ts model file per
 * schema under `generated/api/`. Each model follows this fixed shape:
 *
 *   const XR = t.interface({ ...required props... });
 *   const XO = t.partial({ ...optional props... });
 *   export const X = t.intersection([XR, XO], "X");
 *   export type X = t.TypeOf<typeof X>;
 *
 * When two or more models reference each other (e.g. `Stazioni` has a prop
 * of type `PaStazionePa` and vice versa), the generated files import each
 * other and evaluate `t.intersection(...)`/`t.interface(...)`/`t.partial(...)`
 * eagerly at module-load time. This is a plain JavaScript circular-import
 * limitation (TDZ): whichever module is evaluated first throws
 * `ReferenceError: Cannot access 'X' before initialization` while trying to
 * read the other module's not-yet-initialized export. This is independent of
 * the bundler (reproduced identically with Parcel 2.2.0, 2.3.2, 2.12.0, with
 * and without scope-hoisting).
 *
 * Since `generated/api/` is fully wiped and regenerated by `gen-api-models`
 * on every `generate*` script run (it's gitignored), we can't hand-edit the
 * generated files. Instead this script runs automatically right after code
 * generation and rewrites any model involved in an import cycle to use
 * io-ts's `t.recursion(...)` combinator, which defers evaluation of the
 * circular reference until the type is actually used (by which point every
 * module has finished loading).
 *
 * The cycle detection is fully dynamic (Tarjan's SCC algorithm over the
 * import graph of `generated/api/*.ts`), so this keeps working if the API
 * schema changes and produces different/new circular references.
 */

const path = require("path");
const fs = require("fs");
const { Project, SyntaxKind } = require("ts-morph");

const GENERATED_API_DIR = path.resolve(__dirname, "..", "generated", "api");
const EXCLUDED_FILES = new Set(["client.ts", "requestTypes.ts", "index.ts"]);

function log(msg) {
  // eslint-disable-next-line no-console
  console.log(`[fix-circular-generated-models] ${msg}`);
}

function warn(msg) {
  // eslint-disable-next-line no-console
  console.warn(`[fix-circular-generated-models] WARNING: ${msg}`);
}

if (!fs.existsSync(GENERATED_API_DIR)) {
  warn(`directory not found, nothing to do: ${GENERATED_API_DIR}`);
  process.exit(0);
}

const allFiles = fs
  .readdirSync(GENERATED_API_DIR)
  .filter(f => f.endsWith(".ts") && !EXCLUDED_FILES.has(f));

const baseNames = new Set(allFiles.map(f => path.basename(f, ".ts")));

const project = new Project({
  compilerOptions: {
    target: 99 /* ESNext */,
    module: 99 /* ESNext */,
    strict: false
  },
  skipAddingFilesFromTsConfig: true
});

const sourceFiles = new Map(); // baseName -> SourceFile
for (const file of allFiles) {
  const base = path.basename(file, ".ts");
  const sourceFile = project.addSourceFileAtPath(
    path.join(GENERATED_API_DIR, file)
  );
  sourceFiles.set(base, sourceFile);
}

// ---- 1. Build the import graph between model files -----------------------

const graph = new Map(); // baseName -> Set<baseName>
for (const [base, sourceFile] of sourceFiles) {
  const deps = new Set();
  for (const importDecl of sourceFile.getImportDeclarations()) {
    const spec = importDecl.getModuleSpecifierValue();
    if (!spec.startsWith("./") && !spec.startsWith("../")) {
      continue;
    }
    const importedBase = path.basename(spec);
    if (baseNames.has(importedBase) && importedBase !== base) {
      deps.add(importedBase);
    }
  }
  graph.set(base, deps);
}

// ---- 2. Tarjan's strongly-connected-components algorithm -------------------

function tarjanSCC(g) {
  let index = 0;
  const indices = new Map();
  const lowlink = new Map();
  const onStack = new Map();
  const stack = [];
  const result = [];

  function strongConnect(v) {
    indices.set(v, index);
    lowlink.set(v, index);
    index += 1;
    stack.push(v);
    onStack.set(v, true);

    for (const w of g.get(v) || []) {
      if (!indices.has(w)) {
        strongConnect(w);
        lowlink.set(v, Math.min(lowlink.get(v), lowlink.get(w)));
      } else if (onStack.get(w)) {
        lowlink.set(v, Math.min(lowlink.get(v), indices.get(w)));
      }
    }

    if (lowlink.get(v) === indices.get(v)) {
      const scc = [];
      let w;
      do {
        w = stack.pop();
        onStack.set(w, false);
        scc.push(w);
      } while (w !== v);
      result.push(scc);
    }
  }

  for (const v of g.keys()) {
    if (!indices.has(v)) {
      strongConnect(v);
    }
  }
  return result;
}

const cycles = tarjanSCC(graph).filter(scc => scc.length > 1);

if (cycles.length === 0) {
  log("no circular imports detected among generated models, nothing to fix");
  process.exit(0);
}

log(
  `detected ${cycles.length} circular import group(s): ${cycles
    .map(scc => `{${scc.join(", ")}}`)
    .join(", ")}`
);

// ---- 3. Derive a TS type annotation for a circular property's codec -------

function typeTextForCircularProp(initializer) {
  if (initializer.getKind() === SyntaxKind.Identifier) {
    return { typeText: initializer.getText(), precise: true };
  }
  if (initializer.getKind() === SyntaxKind.CallExpression) {
    const call = initializer.asKindOrThrow(SyntaxKind.CallExpression);
    const calleeText = call.getExpression().getText();
    const args = call.getArguments();
    const firstArg = args[0];
    if (firstArg && firstArg.getKind() === SyntaxKind.Identifier) {
      const inner = firstArg.getText();
      if (/(^|\.)readonlyArray$/.test(calleeText)) {
        return { typeText: `ReadonlyArray<${inner}>`, precise: true };
      }
      if (/(^|\.)array$/.test(calleeText)) {
        return { typeText: `Array<${inner}>`, precise: true };
      }
    }
  }
  // Fallback: keep the codec working at runtime, but widen the compile-time
  // type since we can't safely infer it generically.
  return { typeText: "unknown", precise: false };
}

// ---- 4. For every file in a cyclic group, extract & rewrite circular props -

let patchedCount = 0;

for (const scc of cycles) {
  const sccSet = new Set(scc);

  for (const base of scc) {
    const sourceFile = sourceFiles.get(base);
    if (!sourceFile) {
      warn(`file for "${base}" not found, skipping`);
      continue;
    }

    // Idempotency guard: skip files already patched by this script.
    if (
      sourceFile
        .getFullText()
        .includes("fix-circular-generated-models: patched")
    ) {
      log(`${base}.ts already patched, skipping`);
      continue;
    }

    const rName = `${base}R`;
    const oName = `${base}O`;
    const rDecl = sourceFile.getVariableDeclaration(rName);
    const oDecl = sourceFile.getVariableDeclaration(oName);
    const exportedDecl = sourceFile.getVariableDeclaration(base);
    const typeAlias = sourceFile.getTypeAlias(base);

    if (!rDecl || !oDecl || !exportedDecl || !typeAlias) {
      warn(
        `${base}.ts does not match the expected R/O/intersection shape, skipping`
      );
      continue;
    }

    // Build a map of locally-imported identifiers -> the model file they
    // come from, so we can tell whether a given property references another
    // member of the same cycle.
    const localImportSource = new Map();
    for (const importDecl of sourceFile.getImportDeclarations()) {
      const spec = importDecl.getModuleSpecifierValue();
      if (!spec.startsWith("./") && !spec.startsWith("../")) {
        continue;
      }
      const importedBase = path.basename(spec);
      for (const named of importDecl.getNamedImports()) {
        localImportSource.set(named.getName(), importedBase);
      }
    }

    function isCircularIdentifier(identifierText) {
      const source = localImportSource.get(identifierText);
      return source !== undefined && sccSet.has(source);
    }

    function extractCircularProps(objectLiteral) {
      const circular = [];
      for (const prop of objectLiteral.getProperties()) {
        if (prop.getKind() !== SyntaxKind.PropertyAssignment) {
          continue;
        }
        const initializer = prop.getInitializer();
        if (!initializer) {
          continue;
        }
        const identifiers = [
          ...(initializer.getKind() === SyntaxKind.Identifier
            ? [initializer]
            : []),
          ...initializer.getDescendantsOfKind(SyntaxKind.Identifier)
        ];
        const isCircular = identifiers.some(id =>
          isCircularIdentifier(id.getText())
        );
        if (isCircular) {
          circular.push({
            name: prop.getName(),
            initializerText: initializer.getText(),
            typeText: typeTextForCircularProp(initializer).typeText
          });
        }
      }
      return circular;
    }

    const rObjectLiteral = rDecl
      .getInitializerIfKindOrThrow(SyntaxKind.CallExpression)
      .getArguments()[0]
      .asKindOrThrow(SyntaxKind.ObjectLiteralExpression);
    const oObjectLiteral = oDecl
      .getInitializerIfKindOrThrow(SyntaxKind.CallExpression)
      .getArguments()[0]
      .asKindOrThrow(SyntaxKind.ObjectLiteralExpression);

    const circularRequired = extractCircularProps(rObjectLiteral);
    const circularOptional = extractCircularProps(oObjectLiteral);

    if (circularRequired.length === 0 && circularOptional.length === 0) {
      // This file is part of the cycle transitively but doesn't directly
      // hold a circular field itself; nothing to rewrite here.
      continue;
    }

    // Remove the circular properties from the original object literals.
    for (const { name } of [...circularRequired, ...circularOptional]) {
      const propToRemove =
        rObjectLiteral.getProperty(name) || oObjectLiteral.getProperty(name);
      if (propToRemove) {
        propToRemove.remove();
      }
    }

    const buildTypeMembers = props =>
      props
        .map(({ name, typeText, requiredGroup }) => {
          const optionalMark = requiredGroup ? "" : "?";
          return `  readonly ${JSON.stringify(
            name
          )}${optionalMark}: ${typeText};`;
        })
        .join("\n");

    const requiredMembers = buildTypeMembers(
      circularRequired.map(p => ({ ...p, requiredGroup: true }))
    );
    const optionalMembers = buildTypeMembers(
      circularOptional.map(p => ({ ...p, requiredGroup: false }))
    );
    const extraTypeMembers = [requiredMembers, optionalMembers]
      .filter(Boolean)
      .join("\n");

    const buildRuntimeOverrides = props =>
      props
        .map(
          ({ name, initializerText }) =>
            `${JSON.stringify(name)}: ${initializerText}`
        )
        .join(", ");

    const requiredOverrides = buildRuntimeOverrides(circularRequired);
    const optionalOverrides = buildRuntimeOverrides(circularOptional);

    const mergedRExpr =
      circularRequired.length > 0
        ? `t.interface({ ...${rName}.props, ${requiredOverrides} })`
        : rName;
    const mergedOExpr =
      circularOptional.length > 0
        ? `t.partial({ ...${oName}.props, ${optionalOverrides} })`
        : oName;

    const newBlock = `// NOTE: fix-circular-generated-models: patched to break a circular
// import cycle detected among: ${scc.join(", ")}.
// This block is regenerated automatically by
// scripts/fix-circular-generated-models.js after every \`gen-api-models\` run
// - do not hand-edit \`generated/\` files, they are wiped on each generation.
export type ${base} = t.TypeOf<typeof ${rName}> &
  t.TypeOf<typeof ${oName}> & {
${extraTypeMembers}
  };

export const ${base}: t.Type<${base}> = t.recursion("${base}", () =>
  t.intersection(
    [${mergedRExpr}, ${mergedOExpr}],
    "${base}"
  ) as unknown as t.Type<${base}>
);
`;

    const exportedStatement = exportedDecl.getVariableStatementOrThrow();
    typeAlias.remove();
    exportedStatement.remove();
    sourceFile.insertText(
      sourceFile.getEnd(),
      sourceFile.getFullText().endsWith("\n") ? newBlock : `\n${newBlock}`
    );

    patchedCount += 1;
    log(
      `patched ${base}.ts (required: [${circularRequired
        .map(p => p.name)
        .join(", ")}], optional: [${circularOptional
        .map(p => p.name)
        .join(", ")}])`
    );
  }
}

if (patchedCount > 0) {
  project.saveSync();
  log(`done, patched ${patchedCount} file(s)`);
} else {
  log("cycles detected but no direct circular fields found to patch");
}
